      update estimate_templates set
        keywords = coalesce(keywords, array['tile', 'tiles', 'tiling', 'tiled', 'floor', 'flooring', 'porcelain', 'ceramic', 'grout', 'skirting', 'bathroom', 'kitchen', 'terrace', 'mosaic', 'marble', 'granite', 'adhesive', 'screed']::text[]),
